import{_ as i,C as s,c as o,o as e,a2 as d,b as n,w as a,a as l,G as c,a3 as u}from"./chunks/framework.DkPtUiZm.js";const x=JSON.parse('{"title":"Matrice de couverture web et mobile","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/parite-web-mobile.md","filePath":"contribuer/parite-web-mobile.md","lastUpdated":1795096530000}'),p={name:"contribuer/parite-web-mobile.md"};function m(b,t,h,v,g,f){const r=s("Mermaid");return e(),o("div",null,[t[1]||(t[1]=d('<h1 id="matrice-de-couverture-web-et-mobile" tabindex="-1">Matrice de couverture web et mobile <a class="header-anchor" href="#matrice-de-couverture-web-et-mobile" aria-label="Permalink to &quot;Matrice de couverture web et mobile&quot;">​</a></h1><p>État du code au <strong>17 novembre 2026</strong>, après livraison des éléments partiels et des 17 modules précédemment à créer. Les guides des <a href="./../guides/complements-mobiles.html">compléments</a> et des <a href="./../guides/nouveaux-composants-mobiles.html">nouveaux modules</a> décrivent les API. Cette matrice compare les <strong>115 modules publics</strong> exportés par <code>@sia-ui/react-web</code> au socle <code>@sia-ui/react-native</code> et à son adaptateur Expo Router. Un module peut exporter plusieurs composants, des types ou des fonctions : ce nombre n’est ni un nombre de composants individuels ni un pourcentage de parité fonctionnelle.</p><p>Les <a href="./../guides/adaptations-mobiles.html">13 adaptations mobiles</a> sont désormais implémentées pour la prochaine publication ; les fonctions de bureau exclues de chaque API restent décrites dans ce guide.</p><h2 id="sources-et-methode" tabindex="-1">Sources et méthode <a class="header-anchor" href="#sources-et-methode" aria-label="Permalink to &quot;Sources et méthode&quot;">​</a></h2><ul><li><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-web/src/index.ts" target="_blank" rel="noreferrer">Exports publics web</a>.</li><li><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-native/src/index.ts" target="_blank" rel="noreferrer">Exports publics natifs</a> et <a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-native/src/expo-router.tsx" target="_blank" rel="noreferrer">adaptateur Expo</a>.</li><li>Contrats et implémentations des champs, formulaires, navigation, modales et états natifs ; <a href="./../guides/react-native.html">guide mobile</a>, <a href="./../guides/formulaires-mobiles.html">formulaires mobiles</a> et <a href="./../guides/navigation-mobile-expo-router.html">navigation/session</a>.</li></ul><p>La comparaison porte sur l’existence d’une API publique et sa responsabilité, pas sur la seule présence d’un dessin dans la démo. Un écran d’exemple, une composition manuelle ou une fonction headless ne compte pas comme un composant natif livré. Les exports secondaires d’un module web sont à examiner lors de son portage ; cette matrice ne prétend pas auditer chaque prop, événement ou variante.</p><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td><strong>Disponible</strong></td><td>Un équivalent natif couvre la responsabilité principale ; cela ne signifie ni API identique ni validation complète sur téléphone.</td></tr><tr><td><strong>Partiel</strong></td><td>Une partie du besoin existe, dans un composant plus limité, une composition ou une intégration de démo. Les écarts sont indiqués.</td></tr><tr><td><strong>À créer</strong></td><td>Aucun équivalent public natif dédié ; travail <strong>prévu</strong>, non livré.</td></tr><tr><td><strong>À adapter</strong></td><td>Le besoin doit être repensé pour le tactile, les primitives natives ou le format d’écran ; travail <strong>prévu</strong>, décision ou portage encore à faire.</td></tr></tbody></table><p><strong>Tous les composants natifs restent expérimentaux.</strong> Les tests de comportement, exports Android/iOS/web et essais dans le navigateur ne prouvent pas les gestes, le clavier, les zones sûres, les lecteurs d’écran ou les performances sur appareil. L’utilisateur confirme le 17 novembre avoir testé l’existant dans l’app. Ce retour est conservé comme validation utilisateur ; les nouveaux ajouts de ce lot restent à repasser dans l’app. Cela ne constitue pas une certification de tous les appareils.</p><h2 id="bilan-par-statut" tabindex="-1">Bilan par statut <a class="header-anchor" href="#bilan-par-statut" aria-label="Permalink to &quot;Bilan par statut&quot;">​</a></h2><ul><li><strong>Disponible : 115 modules web.</strong></li><li><strong>Partiel : 0 modules web.</strong></li><li><strong>À créer : 0 modules web.</strong></li><li><strong>À adapter : 0 modules web.</strong></li></ul><p>Les lots ci-dessous sont des <strong>priorités proposées</strong>, pas des engagements de livraison ni des dates. <code>V</code> concerne la consolidation de l’existant ; <code>L1</code> à <code>L5</code> identifient le premier lot où traiter le sujet. Un module partiel peut nécessiter plusieurs incréments.</p><h2 id="matrice-detaillee" tabindex="-1">Matrice détaillée <a class="header-anchor" href="#matrice-detaillee" aria-label="Permalink to &quot;Matrice détaillée&quot;">​</a></h2><h3 id="fondations-visuelles-et-presentation" tabindex="-1">Fondations visuelles et présentation <a class="header-anchor" href="#fondations-visuelles-et-presentation" aria-label="Permalink to &quot;Fondations visuelles et présentation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Typography</code></td><td>Disponible</td><td>Text, Heading, InlineCode</td><td>Titres hiérarchiques avec tailles indépendantes, tons, corps, légendes et code en ligne.</td><td>L1</td></tr><tr><td><code>Button</code></td><td>Disponible</td><td>Button</td><td>Action, variantes, tailles, chargement et animations ; les props DOM deviennent des props Pressable.</td><td>V</td></tr><tr><td><code>IconButton</code></td><td>Disponible</td><td>IconButton</td><td>Surface carrée dédiée, nom accessible obligatoire, tailles, arrondis et contenu personnalisé.</td><td>V</td></tr><tr><td><code>Icons</code></td><td>Disponible</td><td>Icon et 41 icônes SVG SIA</td><td>Tracés communs au web et au mobile, couleur et taille héritées des boutons ; rendu react-native-svg.</td><td>L1</td></tr><tr><td><code>BrandIcon</code></td><td>Disponible</td><td>BrandIcon</td><td>Tracé SVG fourni par l’application, taille, couleur de marque, mode décoratif et contraste clair/sombre. Peer react-native-svg compatible Expo.</td><td>L3</td></tr><tr><td><code>Card</code></td><td>Disponible</td><td>Card et parties composables</td><td>CardHeader, CardBody et CardFooter sont exportés ; title/description existants restent disponibles.</td><td>V</td></tr><tr><td><code>Badge</code></td><td>Disponible</td><td>Badge</td><td>Tons, variantes soft/solid/outline et tailles ; vérifier contraste et grands textes sur appareil.</td><td>V</td></tr><tr><td><code>Avatar</code></td><td>Disponible</td><td>Avatar</td><td>Image, échec avec repli par initiales/contenu, nom accessible et taille.</td><td>V</td></tr><tr><td><code>Label</code></td><td>Disponible</td><td>Label</td><td>Libellé autonome, obligation, désactivation et cible de focus ; association native via nativeID/accessibilityLabelledBy.</td><td>L2</td></tr><tr><td><code>Divider</code></td><td>Disponible</td><td>Divider</td><td>Séparateur horizontal/vertical avec style natif.</td><td>V</td></tr><tr><td><code>Container</code></td><td>Disponible</td><td>Container, Stack</td><td>Largeur maximale, padding, direction, espacement et retour à la ligne configurables.</td><td>L3</td></tr><tr><td><code>AspectRatio</code></td><td>Disponible</td><td>AspectRatio</td><td>Rapport natif validé, largeur adaptative et styles View.</td><td>L5</td></tr><tr><td><code>ScrollArea</code></td><td>Disponible</td><td>ScrollArea</td><td>ScrollView natif avec ref et événements ; les grandes collections restent virtualisées via FlatList.</td><td>L5</td></tr><tr><td><code>ColorModeToggle</code></td><td>Disponible</td><td>ColorModeToggle</td><td>Cycle clair/sombre/système ; provider contrôlé ou état local et notification onModeChange.</td><td>L1</td></tr></tbody></table><h3 id="champs-et-selection" tabindex="-1">Champs et sélection <a class="header-anchor" href="#champs-et-selection" aria-label="Permalink to &quot;Champs et sélection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Input</code></td><td>Disponible</td><td>Input</td><td>Label, aide, erreurs rouges, ref, clavier et focus ; le contrat utilise TextInputProps plutôt que les props HTML.</td><td>V</td></tr><tr><td><code>PasswordInput</code></td><td>Disponible</td><td>PasswordInput</td><td>Visibilité et ref natives ; vérifier le curseur et le clavier sur Android/iOS.</td><td>V</td></tr><tr><td><code>Checkbox</code></td><td>Disponible</td><td>Checkbox</td><td>États coché/non coché/mixte, erreurs et désactivation ; activation tactile à valider sur appareil.</td><td>V</td></tr><tr><td><code>Switch</code></td><td>Disponible</td><td>Switch</td><td>Identité SIA, tailles, focus et animations ; bascule par appui, sans glissement latéral du pouce.</td><td>V</td></tr><tr><td><code>RadioGroup</code></td><td>Disponible</td><td>RadioGroup</td><td>Choix unique et options désactivées ; pas d’export Radio individuel comparable au web.</td><td>V</td></tr><tr><td><code>Select</code></td><td>Disponible</td><td>Select dans BottomSheet</td><td>Recherche locale ou distante annulable, liste virtualisée et réessai ; pas de pagination distante.</td><td>V</td></tr><tr><td><code>MultiSelect</code></td><td>Disponible</td><td>MultiSelect</td><td>Choix multiples, résumé des libellés et confirmation dans une feuille.</td><td>V</td></tr><tr><td><code>Autocomplete</code></td><td>Disponible</td><td>Autocomplete</td><td>Suggestions distantes annulables et valeur libre optionnelle dans une feuille ; pas de menu DOM.</td><td>V</td></tr><tr><td><code>ReferenceSelect</code></td><td>Disponible</td><td>ReferenceSelect</td><td>Choix métier avec description, recherche locale/distante, chargement, erreurs et conservation de valeur.</td><td>L3</td></tr><tr><td><code>SearchInput</code></td><td>Disponible</td><td>SearchInput</td><td>Effacement, validation et debounce configurable avec annulation au démontage.</td><td>V</td></tr><tr><td><code>Textarea</code></td><td>Disponible</td><td>Textarea</td><td>Contrôle multiligne, hauteur minimale et retour à la ligne ; pas de redimensionnement DOM.</td><td>V</td></tr><tr><td><code>InputNumber</code></td><td>Disponible</td><td>InputNumber</td><td>Brouillon intermédiaire, bornes, pas, précision et boutons masquables ; formatage local avancé absent.</td><td>V</td></tr><tr><td><code>CurrencyInput</code></td><td>Disponible</td><td>CurrencyInput</td><td>Groupement et décimales selon la locale ; précision par devise, brouillons et bornes conservés.</td><td>V</td></tr><tr><td><code>PhoneInput</code></td><td>Disponible</td><td>PhoneInput</td><td>Sélecteur recherchable de pays configurés, onCountryChange, normalisation et conservation des saisies invalides.</td><td>V</td></tr><tr><td><code>OtpInput</code></td><td>Disponible</td><td>OtpInput</td><td>Cases visuelles sur une saisie native unique : collage, suggestion système, masquage et mode champ classique.</td><td>V</td></tr><tr><td><code>TagsInput</code></td><td>Disponible</td><td>TagInput / TagsInput</td><td>Ajout par validation ou bouton, collage séparé par virgules, unicité, limites et retrait tactile.</td><td>L2</td></tr><tr><td><code>Slider</code></td><td>Disponible</td><td>Slider</td><td>Logique headless commune, geste tactile simple/plage, bornes/pas et actions d’accessibilité.</td><td>L2</td></tr><tr><td><code>Rating</code></td><td>Disponible</td><td>Rating</td><td>Étoiles tactiles, maximum configurable, effacement et état lecture seule.</td><td>L2</td></tr><tr><td><code>Toggle</code></td><td>Disponible</td><td>Toggle / ToggleGroup</td><td>État pressé contrôlé/local ; groupes simples/multiples, effacement facultatif, tailles, tons, variantes et désactivation.</td><td>L2</td></tr><tr><td><code>ColorPicker</code></td><td>Disponible</td><td>ColorPicker</td><td>Nuancier personnalisable, sélection tactile, saisie hexadécimale et validation du formulaire.</td><td>L4</td></tr><tr><td><code>FileUpload</code></td><td>Disponible</td><td>FileUpload et NativeFilePickerProvider</td><td>Sélection injectable, type/taille/nombre, retrait, annulation et erreurs. Comme sur le web, le transfert réseau appartient à l’application.</td><td>V</td></tr><tr><td><code>ImageUpload</code></td><td>Disponible</td><td>ImageUpload</td><td>Photothèque/caméra via adaptateur, aperçu et limites. Le web ne fournit pas non plus recadrage/compression/transfert intégrés.</td><td>V</td></tr><tr><td><code>SecretFields</code></td><td>Disponible</td><td>SecretFields</td><td>Valeurs masquées, noms enregistrés sans valeur relue, rotation, modèles, validation de noms/doublons et identité des champs conservée.</td><td>L3</td></tr></tbody></table><h3 id="formulaires-et-parcours" tabindex="-1">Formulaires et parcours <a class="header-anchor" href="#formulaires-et-parcours" aria-label="Permalink to &quot;Formulaires et parcours&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Field</code></td><td>Disponible</td><td>Field / FormField</td><td>Tous les types web sont reconnus, dont champs avancés et hidden ; alias datetime et extensions dateRange/dateTime. Éditeur HTML via adaptateur explicite.</td><td>V</td></tr><tr><td><code>FormField</code></td><td>Disponible</td><td>FormField</td><td>Liaison adaptateur, événements TextInput, références stables, erreurs et états ; types natifs uniquement.</td><td>V</td></tr><tr><td><code>Form</code></td><td>Disponible</td><td>Form et FormContainer</td><td>Dispatcher complet, groupes, validation JSON/couleur/nombre, premier invalide et barre clavier ; champs avancés intégrés.</td><td>V</td></tr><tr><td><code>Steps</code></td><td>Disponible</td><td>Steps</td><td>États, connecteurs animés, orientation, étape contrôlée et callback ; validation externe et statusLabels traduisibles.</td><td>V</td></tr><tr><td><code>UnsavedChangesGuard</code></td><td>Disponible</td><td>SiaExpoUnsavedChangesGuard</td><td>Retour/suppression de route et shell protégés. Les liens personnalisés passent par useSiaExpoNavigation : contrat d’intégration, pas fonctionnalité absente.</td><td>V</td></tr></tbody></table><h3 id="navigation-structure-et-session" tabindex="-1">Navigation, structure et session <a class="header-anchor" href="#navigation-structure-et-session" aria-label="Permalink to &quot;Navigation, structure et session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>AppShell</code></td><td>Disponible</td><td>AppShell et SiaExpoLayout</td><td>Disposition responsive, clavier, zones sûres et slots ; routes privées via l’adaptateur Expo optionnel.</td><td>V</td></tr><tr><td><code>Sidebar</code></td><td>Disponible</td><td>Sidebar</td><td>Arbre, permissions, rail, sous-menus et variante flottante ; tester largeur, focus et grands textes sur appareil.</td><td>V</td></tr><tr><td><code>Tabs</code></td><td>Disponible</td><td>Tabs, TabsList, TabsTrigger, TabsContent</td><td>Vues contrôlées/locales, panneaux conservés avec fondu/glissement et fond animé ; navigation externe par flèches/Home/End encore à compléter.</td><td>V</td></tr><tr><td><code>Accordion</code></td><td>Disponible</td><td>Accordion</td><td>Hook partagé, single/multiple, variantes, disabled, contenu conservé et hauteur animée ; gestes et focus natifs à valider.</td><td>V</td></tr><tr><td><code>Breadcrumb</code></td><td>Disponible</td><td>Breadcrumb</td><td>Parent et page courante sur téléphone ; ancêtres en feuille, fil complet sur tablette.</td><td>L5</td></tr><tr><td><code>PageHeader</code></td><td>Disponible</td><td>PageHeader</td><td>Titre, description, retour et actions adaptatives ; rendus natifs, sans contrat DOM.</td><td>V</td></tr><tr><td><code>AuthLayout</code></td><td>Disponible</td><td>AuthLayout</td><td>Page réutilisable avec titre, logo, description, aside adaptatif, footer, largeur et défilement clavier.</td><td>L3</td></tr><tr><td><code>AccountMenu</code></td><td>Disponible</td><td>AccountMenu</td><td>Identité, e-mail, avatar, actions et permissions DropdownMenu ; déconnexion asynchrone injectée, sans deuxième session.</td><td>L3</td></tr><tr><td><code>RequireSession</code></td><td>Disponible</td><td>RequireSession</td><td>Même SessionStore SIA : vérification, profil incomplet, refus et callbacks ; ne constitue pas une autorisation serveur.</td><td>V</td></tr><tr><td><code>PermissionGate</code></td><td>Disponible</td><td>PermissionGate</td><td>Évaluateur injecté, règle déclarée refusée sans évaluateur ; autorisation serveur toujours nécessaire.</td><td>V</td></tr><tr><td><code>PermissionMatrix</code></td><td>Disponible</td><td>PermissionMatrix</td><td>Groupes tactiles, sélection partielle, jokers, droits non accordables et permissions inconnues conservées ; contrôle serveur applicatif.</td><td>L5</td></tr></tbody></table><h3 id="couches-flottantes-et-actions-contextuelles" tabindex="-1">Couches flottantes et actions contextuelles <a class="header-anchor" href="#couches-flottantes-et-actions-contextuelles" aria-label="Permalink to &quot;Couches flottantes et actions contextuelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Modal</code></td><td>Disponible</td><td>Modal</td><td>Ouverture contrôlée, footer, clavier, Retour et défilement ; APIs et garanties de focus DOM non transposables telles quelles.</td><td>V</td></tr><tr><td><code>Drawer</code></td><td>Disponible</td><td>Drawer</td><td>Quatre positions, taille bornée, footer, Retour/Échap, fond, thème, clavier et animations ; ref open/close/toggle.</td><td>L3</td></tr><tr><td><code>Overlay</code></td><td>Disponible</td><td>Overlay</td><td>Couche NativeModal publique, fond configurable, fermeture contrôlée, thème local et restitution de focus ; réutilisée par Drawer.</td><td>L1</td></tr><tr><td><code>ConfirmDialog</code></td><td>Disponible</td><td>ConfirmDialog</td><td>Action asynchrone verrouillée, erreur réessayable, ton danger et confirmation textuelle.</td><td>V</td></tr><tr><td><code>DropdownMenu</code></td><td>Disponible</td><td>DropdownMenu et ContextMenu</td><td>Actions, droits, attente/erreur, confirmation dans la surface, feuille ou ancrage et appui long avec bouton alternatif.</td><td>V</td></tr><tr><td><code>Popover</code></td><td>Disponible</td><td>Popover adaptatif</td><td>Ancrage mesuré et borné, repli en feuille, Retour/Échap ; les menus ancrés se ferment à l’ouverture du clavier. Existant testé dans l’app par l’utilisateur.</td><td>V</td></tr><tr><td><code>Tooltip</code></td><td>Disponible</td><td>Tooltip</td><td>Aide par appui, appui long et clavier ; feuille sur téléphone, ancrage sur tablette.</td><td>L5</td></tr><tr><td><code>HoverCard</code></td><td>Disponible</td><td>HoverCard</td><td>Aperçu au toucher via Popover/feuille, sans dépendance au survol.</td><td>L5</td></tr><tr><td><code>CommandPalette</code></td><td>Disponible</td><td>CommandPalette</td><td>Recherche locale, droits, actions asynchrones, erreurs et liste en feuille ; Ctrl/Cmd+K dans la cible web.</td><td>L5</td></tr><tr><td><code>Tour</code></td><td>Disponible</td><td>Tour</td><td>Préparation asynchrone de route/défilement injectée, cible native mesurée, spotlight et progression accessible.</td><td>L5</td></tr></tbody></table><h3 id="retours-utilisateur-et-etats" tabindex="-1">Retours utilisateur et états <a class="header-anchor" href="#retours-utilisateur-et-etats" aria-label="Permalink to &quot;Retours utilisateur et états&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Alert</code></td><td>Disponible</td><td>Alert</td><td>Message sémantique, ton, action et fermeture contrôlée ; annoncer le contenu sans masquer les boutons.</td><td>V</td></tr><tr><td><code>Toast</code></td><td>Disponible</td><td>Toast contrôlé et Toaster partagé</td><td>Pile, mises à jour, actions et placements reliés au store existant ; un hôte par store, pas de surcouche au-dessus des fenêtres Modal natives.</td><td>V</td></tr><tr><td><code>Spinner</code></td><td>Disponible</td><td>Spinner</td><td>Dessins SIA ring/double-ring/dots, cinq tailles xs–xl, tons et current via contexte natif ; arrêt en arrière-plan et mouvement réduit.</td><td>V</td></tr><tr><td><code>Skeleton</code></td><td>Disponible</td><td>Skeleton</td><td>Dimensions, rayon et pulsation ; statique lorsque le mouvement est réduit.</td><td>V</td></tr><tr><td><code>Progress</code></td><td>Disponible</td><td>Progress</td><td>Remplissage borné animé/interruptible, maximum, attente indéterminée et valeur accessible.</td><td>V</td></tr><tr><td><code>EmptyState</code></td><td>Disponible</td><td>EmptyState</td><td>Icône, titre, description, action et mode compact dans un composant public.</td><td>L3</td></tr><tr><td><code>ErrorState</code></td><td>Disponible</td><td>ErrorState</td><td>Erreur de requête, message, action et réessai asynchrone verrouillé ; distinct de la boundary de page.</td><td>L3</td></tr><tr><td><code>AsyncState</code></td><td>Disponible</td><td>AsyncState</td><td>Chargement, vide, erreur, réessai et actions de repli composés avec StateScreen.</td><td>V</td></tr></tbody></table><h3 id="dates-heures-et-agendas" tabindex="-1">Dates, heures et agendas <a class="header-anchor" href="#dates-heures-et-agendas" aria-label="Permalink to &quot;Dates, heures et agendas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Calendar</code></td><td>Disponible</td><td>Calendar</td><td>Calendrier SIA tactile, locale, année recherchable, jours indisponibles et fondu de mois ; navigation clavier de bureau à compléter.</td><td>V</td></tr><tr><td><code>DatePicker</code></td><td>Disponible</td><td>DatePicker</td><td>Jour civil contrôlé, bornes et brouillon ; mois complet ajusté à la feuille sans défilement interne.</td><td>V</td></tr><tr><td><code>DateTimePicker</code></td><td>Disponible</td><td>DateTimePicker</td><td>Date/heure en étapes avec brouillon commun. Fuseau métier et heure d’été restent applicatifs sur les deux plateformes.</td><td>V</td></tr><tr><td><code>DateRangePicker</code></td><td>Disponible</td><td>DateRangePicker</td><td>Début/fin, ordre et bornes, remise au début si le second choix est antérieur ; validation métier des jours intérieurs externe.</td><td>V</td></tr><tr><td><code>TimePicker</code></td><td>Disponible</td><td>TimePicker</td><td>Heure HH:mm, bornes, pas de minutes et affichage 12/24 h ; contrôle SIA en feuille.</td><td>V</td></tr><tr><td><code>TimeRangePicker</code></td><td>Disponible</td><td>TimeRangePicker</td><td>Deux heures sur roues, brouillon, confirmation, limites, pas de minutes et franchissement de minuit explicite.</td><td>L4</td></tr><tr><td><code>MonthPicker</code></td><td>Disponible</td><td>MonthPicker</td><td>Mois civil YYYY-MM, année navigable, bornes, lecture seule et brouillon annulable.</td><td>L4</td></tr><tr><td><code>WeekPicker</code></td><td>Disponible</td><td>WeekPicker</td><td>Valeur ISO YYYY-Www, semaine lundi–dimanche visible, contrôle des années ISO et bornes sur toute la semaine.</td><td>L4</td></tr><tr><td><code>YearPicker</code></td><td>Disponible</td><td>YearPicker</td><td>Années bornées 1–9999, sélection virtualisée, confirmation et lecture seule.</td><td>L4</td></tr><tr><td><code>MiniCalendar</code></td><td>Disponible</td><td>MiniCalendar</td><td>Composition compacte du Calendar natif ; thèmes, bornes, sélection et semaine commune.</td><td>L4</td></tr><tr><td><code>EventCalendar</code></td><td>Disponible</td><td>EventCalendar</td><td>Mois avec liste du jour, semaine/jour/agenda chronologiques, périodes et événements multi-jours headless ; pas de déplacement horaire par glisser.</td><td>L5</td></tr><tr><td><code>EventManager</code></td><td>Disponible</td><td>EventManager</td><td>Agenda par jour avec Calendar, liste, détail, création/modification et suppression confirmée ; erreurs serveur et permissions injectées. EventCalendar fournit les vues mobiles en listes chronologiques.</td><td>L5</td></tr><tr><td><code>DateRangeFilter</code></td><td>Disponible</td><td>DateRangeFilter</td><td>Période contrôlée, raccourcis, bornes, lecture seule et remise à zéro via callback.</td><td>L4</td></tr></tbody></table><h3 id="listes-donnees-et-ecrans-metier" tabindex="-1">Listes, données et écrans métier <a class="header-anchor" href="#listes-donnees-et-ecrans-metier" aria-label="Permalink to &quot;Listes, données et écrans métier&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Resource</code></td><td>Disponible</td><td>ResourceDefinitionCore et defineResource natif</td><td>Métadonnées, permissions et sources partagées ; formulaires et renderers natifs dédiés. Séparer le rendu DOM du rendu natif est volontaire.</td><td>V</td></tr><tr><td><code>CrudPage</code></td><td>Disponible</td><td>CrudPage natif</td><td>Liste, fiche, création/édition et suppression confirmée, droits et garde de saisie injectable ; pas de parité intégrale des props web.</td><td>V</td></tr><tr><td><code>DataTable</code></td><td>Disponible</td><td>DataTable / ResourceList</td><td>Colonnes sur tablette, lignes sur téléphone, présentation forcée, tri, pagination, défilement horizontal et sélection globale par allKeys autorisées du résultat filtré.</td><td>V</td></tr><tr><td><code>FiltersBar</code></td><td>Disponible</td><td>FiltersBar</td><td>Recherche temporisée, filtres simples en feuille, annulation/validation et résumé ; filtres complexes non portés.</td><td>V</td></tr><tr><td><code>Pagination</code></td><td>Disponible</td><td>Pagination</td><td>Variantes compacte/numérotée et total ; pas de curseurs ou chargement infini.</td><td>V</td></tr><tr><td><code>Descriptions</code></td><td>Disponible</td><td>Descriptions</td><td>Paires libellé/valeur verticales ou en ligne, rendus natifs personnalisables.</td><td>V</td></tr><tr><td><code>EntityMeta</code></td><td>Disponible</td><td>EntityMeta</td><td>Statut, identifiant sélectionnable, auteurs et dates relatives ; variantes verticales/en ligne.</td><td>V</td></tr><tr><td><code>AuditMeta</code></td><td>Disponible</td><td>AuditMeta</td><td>Événements, auteurs, détails, dates et état vide ; la source et la fiabilité du journal restent applicatives.</td><td>V</td></tr><tr><td><code>Statistic</code></td><td>Disponible</td><td>Statistic</td><td>Nombre/devise/pourcentage, tailles, tendance et sens favorable configurables ; transition réduite selon la préférence système.</td><td>V</td></tr><tr><td><code>StatCard</code></td><td>Disponible</td><td>StatCard</td><td>Contour/douce/accentuée, action, description, chargement et erreur réessayable.</td><td>V</td></tr><tr><td><code>KpiGrid</code></td><td>Disponible</td><td>KpiGrid</td><td>Colonnes adaptées à la largeur intérieure mesurée ; pas de moteur de graphiques.</td><td>V</td></tr><tr><td><code>AmountDisplay</code></td><td>Disponible</td><td>AmountDisplay</td><td>Devise, signe et locale partagés, tons et valeur absente.</td><td>V</td></tr><tr><td><code>RelativeTime</code></td><td>Disponible</td><td>RelativeTime</td><td>Rafraîchissement actif, pause en arrière-plan et reprise immédiate ; date complète accessible.</td><td>V</td></tr><tr><td><code>DurationDisplay</code></td><td>Disponible</td><td>DurationDisplay</td><td>Formats court/long/horloge ; textStyle natif séparé du style de formatage.</td><td>V</td></tr><tr><td><code>Timeline</code></td><td>Disponible</td><td>Timeline</td><td>Ligne/cartes, repères, densité, inversion, attente et actions ; liste non virtualisée.</td><td>V</td></tr><tr><td><code>Tree</code></td><td>Disponible</td><td>Tree</td><td>Expansion, recherche de chemins, sélection indépendante simple/multiple, disabled hérité ; cascade et clavier de bureau complet prévus.</td><td>V</td></tr><tr><td><code>TreeSelect</code></td><td>Disponible</td><td>TreeSelect</td><td>Brouillon en feuille, recherche intégrée, chemins, validation/annulation et variantes de champ ; branches distantes prévues.</td><td>V</td></tr><tr><td><code>Transfer</code></td><td>Disponible</td><td>Transfer</td><td>Résumé et brouillon en feuille avec recherche, confirmation/annulation et protection des clés verrouillées/inconnues.</td><td>L5</td></tr><tr><td><code>Chart</code></td><td>Disponible</td><td>Chart</td><td>Courbe, aire et barres SVG natives ; légende, sélection au toucher et lecture par boutons. Pas de zoom ou axes secondaires.</td><td>L5</td></tr><tr><td><code>QrCode</code></td><td>Disponible</td><td>QRCode</td><td>Encodeur UTF-8 local, SVG, zone calme et correction ; partage de valeur natif ou export SVG injecté.</td><td>L5</td></tr></tbody></table><h3 id="editeurs-supervision-et-outils-specialises" tabindex="-1">Éditeurs, supervision et outils spécialisés <a class="header-anchor" href="#editeurs-supervision-et-outils-specialises" aria-label="Permalink to &quot;Éditeurs, supervision et outils spécialisés&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>JsonView</code></td><td>Disponible</td><td>JsonView</td><td>Arbre dépliable borné en profondeur/nœuds, cycles, source invalide, virtualisation ou intégration sans défilement et copie injectable avec erreur réessayable.</td><td>L5</td></tr><tr><td><code>JsonEditor</code></td><td>Disponible</td><td>JsonEditor</td><td>Texte JSON, valeur analysée, erreur rouge, formatage au blur et clavier multiligne.</td><td>L5</td></tr><tr><td><code>MarkdownEditor</code></td><td>Disponible</td><td>MarkdownEditor</td><td>Écriture multiligne et aperçu injectable ; comme sur le web, aucun moteur Markdown imposé.</td><td>L5</td></tr><tr><td><code>RichTextEditor</code></td><td>Disponible</td><td>RichTextEditor et NativeRichTextProvider</td><td>Surface injectable, gras/italique/liste, HTML ; adaptateur WebView Android/iOS optionnel livré dans une entrée séparée, exemple navigateur dédié.</td><td>L5</td></tr><tr><td><code>ActivityLog</code></td><td>Disponible</td><td>ActivityLog</td><td>Journal virtualisé composant ResourceList, requête externe, recherche, filtres, pagination, états et actualisation ; aucun filtrage serveur implicite.</td><td>L5</td></tr><tr><td><code>LogStream</code></td><td>Disponible</td><td>LogStream</td><td>Liste bornée et virtualisée, pause/suivi, filtres et gel en arrière-plan ; transport réseau externe.</td><td>L5</td></tr><tr><td><code>JobProgress</code></td><td>Disponible</td><td>JobProgress</td><td>Statut, progression déterminée/indéterminée, étapes, essais, durée et actions asynchrones verrouillées ; erreur réessayable.</td><td>L5</td></tr><tr><td><code>LiveIndicator</code></td><td>Disponible</td><td>LiveIndicator</td><td>Connexion en cours/ouverte/fermée, libellés, mode compact, animation réduite et arrêt du mouvement en arrière-plan.</td><td>L5</td></tr><tr><td><code>Timer</code></td><td>Disponible</td><td>Timer</td><td>Sens montant/descendant, pause, reprise, changement de durée et calcul sur horodatage ; arrêt des intervalles en arrière-plan et fin unique.</td><td>L5</td></tr><tr><td><code>Countdown</code></td><td>Disponible</td><td>Countdown</td><td>Contrat Timer descendant, durée et fin unique ; rattrapage au retour au premier plan.</td><td>L5</td></tr><tr><td><code>ResizablePanel</code></td><td>Disponible</td><td>ResizablePanel</td><td>Panneaux ajustables sur tablette avec poignée et boutons ; empilement ou onglets sur téléphone.</td><td>L5</td></tr></tbody></table><h2 id="briques-natives-sans-module-web-du-meme-nom" tabindex="-1">Briques natives sans module web du même nom <a class="header-anchor" href="#briques-natives-sans-module-web-du-meme-nom" aria-label="Permalink to &quot;Briques natives sans module web du même nom&quot;">​</a></h2><p>Ces ajouts ne doivent pas être comptés comme des modules web supplémentaires. Ils répondent à des usages mobiles ou regroupent plusieurs responsabilités web.</p><table tabindex="0"><thead><tr><th>API native disponible</th><th>Relation avec le web</th><th>Ce qui reste à distinguer</th></tr></thead><tbody><tr><td>SiaNativeProvider, NativeThemeScope, useNativeTheme</td><td>Thème, locale et tokens communs</td><td>Distribution Uniwind, zones de portail et polices ; pas une API DOM interchangeable.</td></tr><tr><td>BottomBar</td><td>Navigation principale mobile ; pas d’export BottomBar web dans l’inventaire</td><td>Capsule/trait/minimal, styles, couleurs, badges, Plus et animations configurables sont livrés ; cela ne remplace pas Tabs dans une page.</td></tr><tr><td>BottomSheet</td><td>Besoin proche d’un Drawer web positionné en bas</td><td>Hauteur contrôlée, fermeture par poignée et primitives Modal sont livrées ; snap points et actions d’accessibilité par poignée sont livrés ; déplacement sur le contenu du ScrollView interne livré : tirer vers le bas à son début, ou vers le haut pour agrandir un snap point. Les listes virtualisées personnalisées gardent la poignée comme contrôle du geste.</td></tr><tr><td>FormContainer, FormSection, KeyboardScrollView</td><td>Conteneur, regroupement et saisie libre avec clavier</td><td>Validation via FormAdapter et verrou d’envoi présents ; Form/Field génèrent et lient tous les types web et les extensions de dates natives ; le HTML utilise un adaptateur explicite.</td></tr><tr><td>StateScreen</td><td>Présentation commune de plusieurs états de page</td><td>404, refus, attente et action de reprise possibles ; AsyncState compose maintenant ces états pour les requêtes.</td></tr><tr><td>SiaExpoStack, SiaExpoLayout</td><td>Navigation protégée sur le SessionStore existant</td><td>Groupe privé, permission de route et retrait d’historique ; entrée optionnelle <code>@sia-ui/react-native/expo-router</code>.</td></tr><tr><td>useExpoSessionReturn, SiaExpoErrorBoundary</td><td>Reprise de route et erreur d’écran</td><td>Retour interne après connexion et réessai sont livrés ; aucune session parallèle n’est créée.</td></tr></tbody></table><h2 id="fondations-partagees-reutiliser-pas-annoncer-un-rendu-absent" tabindex="-1">Fondations partagées : réutiliser, pas annoncer un rendu absent <a class="header-anchor" href="#fondations-partagees-reutiliser-pas-annoncer-un-rendu-absent" aria-label="Permalink to &quot;Fondations partagées : réutiliser, pas annoncer un rendu absent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Socle existant</th><th>Réutilisation possible</th><th>Limite actuelle</th></tr></thead><tbody><tr><td>Tokens de couleur, espacement, typographie et mouvement</td><td>Même identité, thèmes et vocabulaire de mouvement</td><td>Les animations et les composants restent des implémentations propres à chaque plateforme.</td></tr><tr><td>SessionStore, useSession et règles d’accès headless</td><td>Même session pour la navigation, l’expiration et les droits</td><td>Le stockage des secrets et les appels d’authentification réels restent ceux de l’application ; la démo native est locale.</td></tr><tr><td>FormAdapter, useLocalForm et validation partagée</td><td>Même contrat de valeurs/erreurs, validation asynchrone selon l’adaptateur</td><td>FormContainer ne génère pas les champs et n’injecte pas automatiquement disabled dans ses enfants.</td></tr><tr><td>Arbres de navigation, disclosure, pagination, recherche différée, accordéon et slider headless</td><td>Réutiliser les calculs et états sans DOM</td><td>L’existence du hook ne livre ni la gestuelle ni le composant natif correspondant.</td></tr><tr><td>Toast store et logique de temps réel</td><td>Réutiliser des annonces ou statuts</td><td>Toast contrôlé et Toaster connecté au store sont disponibles ; cycle de vie et empilement à valider sur appareil.</td></tr><tr><td>Utilitaires de montants, dates, téléphones et validation</td><td>Éviter de réécrire le formatage et les règles métier</td><td>Ne signifie pas qu’un champ ou un composant d’affichage natif existe.</td></tr><tr><td>Module API partagé</td><td>Brancher une application mobile à ses services</td><td>L’intégration réelle avec stockage, réseau et session doit être vérifiée dans l’application consommatrice.</td></tr><tr><td>Définition de ressource</td><td>Contrat commun de métadonnées avec adaptateurs de champs</td><td>Métadonnées et permissions extraites dans headless ; adaptateurs de champs propres au web et au natif.</td></tr></tbody></table><p>Le package natif ne doit pas importer les rendus de <code>@sia-ui/react-web</code>. Un contrat commun doit vivre dans une couche sans DOM ; les valeurs métier et la session peuvent être communes tout en gardant des interfaces adaptées au téléphone.</p>',36)),(e(),n(u,null,{default:a(()=>[c(r,{id:"mermaid-2512",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tokens%5B%22Tokens%20communs%20existants%22%5D%20--%3E%20Web%5B%22Rendus%20web%20existants%22%5D%0A%20%20Tokens%20--%3E%20Native%5B%22Rendus%20natifs%20existants%22%5D%0A%20%20Shared%5B%22Session%2C%20formulaires%20et%20comportements%20headless%20existants%22%5D%20--%3E%20Web%0A%20%20Shared%20--%3E%20Native%0A%20%20Matrix%5B%22Matrice%20de%20couverture%22%5D%20--%3E%20Planned%5B%22Pr%C3%A9vu%20%3A%20contrats%20et%20adaptations%20manquants%22%5D%0A%20%20Planned%20-.-%3E%20Shared%0A%20%20Planned%20-.-%3E%20Mobile%5B%22Pr%C3%A9vu%20%3A%20composants%20et%20%C3%A9crans%20mobiles%22%5D%0A%20%20Native%20--%3E%20QA%5B%22Validation%20sur%20Android%20et%20iOS%22%5D%0A%20%20Mobile%20-.-%3E%20QA%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<h2 id="ecarts-transversaux-a-suivre" tabindex="-1">Écarts transversaux à suivre <a class="header-anchor" href="#ecarts-transversaux-a-suivre" aria-label="Permalink to &quot;Écarts transversaux à suivre&quot;">​</a></h2><p>Ces points ne sont pas des modules supplémentaires et ne changent pas les comptes ci-dessus. Ils concernent plusieurs composants à la fois.</p><table tabindex="0"><thead><tr><th>Sujet</th><th>Existant</th><th>Travail restant / priorité</th></tr></thead><tbody><tr><td>Configuration par défaut</td><td>SiaNativeProvider transmet <code>defaults</code> au provider headless</td><td>Button, Badge, Spinner, Alert, Avatar, Skeleton, Progress, Steps, Tabs, Accordion, Input, Select, MultiSelect, Autocomplete, Calendar, ResourceList, Popover, DropdownMenu, Tree, TreeSelect, BulkActionBar et les neuf briques d’affichage métier lisent leurs clés locales. Généralisation aux autres composants encore prévue ; ne pas annoncer une couverture globale.</td></tr><tr><td>Langues</td><td>Provider et plusieurs composants utilisent la locale partagée</td><td>Certains textes de l’adaptateur Expo et de la démo sont directement en français ; compléter l’internationalisation des textes de bibliothèque en L1/L2.</td></tr><tr><td>Personnalisation</td><td>Tokens, palettes locales et réglages détaillés de navigation</td><td>Les variantes, slots et props de personnalisation ne sont pas uniformes entre composants ; les vérifier lors de chaque portage.</td></tr><tr><td>Gestes et focus</td><td>Pressable, Animated, poignée PanResponder, premières annonces d’accessibilité</td><td>Focus initial/restauré, conflits de gestes, clavier et grands textes : validation V puis amélioration par composant.</td></tr><tr><td>Empilement des couches</td><td>Modal, BottomSheet et tiroir ont des implémentations natives</td><td>Vérifier les ouvertures imbriquées, le Retour et les annonces ; ne pas déduire la parité des garanties d’overlay DOM.</td></tr><tr><td>Distribution</td><td>Package natif, thème Uniwind et entrée Expo optionnelle</td><td>La CLI de copie des composants web ne distribue pas encore ces rendus natifs. Compatibilité annoncée limitée aux versions documentées du socle, pas à tout projet Expo/React Native.</td></tr></tbody></table><h2 id="ordre-de-realisation-et-avancement" tabindex="-1">Ordre de réalisation et avancement <a class="header-anchor" href="#ordre-de-realisation-et-avancement" aria-label="Permalink to &quot;Ordre de réalisation et avancement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lot</th><th>Travail et avancement</th><th>Utilité et critère de sortie</th></tr></thead><tbody><tr><td>V — Consolider l’existant</td><td>Tester navigation, champs, clavier, zones sûres, Retour, expiration, 404 et mouvement réduit sur Android/iOS</td><td>Documenter appareil, système et révision ; fermer les anomalies observées sans présenter les exports comme des tests sur téléphone.</td></tr><tr><td>L1a — États et petites briques</td><td><strong>Socle livré</strong> : Badge, Avatar, Alert, Spinner, Skeleton, Progress, Divider, IconButton, parties Card, variantes Text et Toaster ; compléter les variantes et défauts transversaux</td><td>Construire un écran cohérent sans recréer les messages, les chargements ni une seconde API de notifications.</td></tr><tr><td>L1b — Organisation d’écran</td><td><strong>Livré</strong> : Steps, Tabs de contenu et Accordion ; compléter le clavier externe et les validations sur appareil</td><td>Démontrer un formulaire en étapes avec états current/done/upcoming/error, navigation contrôlée, sections et annonces accessibles. La validation métier reste dans le formulaire.</td></tr><tr><td>L1c — BottomSheet avancée</td><td><strong>Livré</strong> : positions d’arrêt, hauteur bornée, poignée, durée, actions d’accessibilité, agrandissement au clavier et entraînement par le contenu du ScrollView interne</td><td>Démontrer une sélection longue et un formulaire sans conflit de gestes, avec mouvement réduit. La poignée reste disponible pour les listes virtualisées personnalisées ; nouveaux gestes à repasser sur appareil.</td></tr><tr><td>L2 — Formulaires complets</td><td><strong>Socle livré</strong> : Field/Form, Select distant, MultiSelect, champs spécialisés, confirmation et protection Expo ; champs avancés livrés ; nouveaux contrôles à repasser sur appareil</td><td>Démontrer saisie, recherche annulable, erreurs rouges, double envoi bloqué et abandon confirmé ; conserver focus, valeur et position lors des rendus.</td></tr><tr><td>L3 — Parcours métier</td><td>Contrat Resource sans DOM, liste/cartes virtualisées, filtres, pagination, détail et édition ; état asynchrone commun</td><td>Démontrer un parcours liste → détail → modification avec droits, actualisation, vide/erreur/réessai et conservation des filtres. Socle Contacts testé par l’utilisateur ; DataTable et sélection globale ajoutés dans ce lot.</td></tr><tr><td>L4 — Dates et fichiers</td><td><strong>Socle livré</strong> : calendrier, date/heure/période, sélection documents/images ; couleur livrée ; transfert réseau applicatif comme sur le web, nouveaux contrôles à repasser sur appareil</td><td>Valider valeurs, bornes, locale/fuseau selon le contrat, permissions système et annulation sur appareil. Choisir les dépendances compatibles avec Expo.</td></tr><tr><td>L5 — Besoins spécialisés</td><td>Arbres, éditeurs, agenda, journal et suivi livrés ; 13 adaptations mobiles livrées, dont graphiques SVG, agenda multivue et journal borné</td><td>Implémenter à partir d’un usage identifié ; ne pas reproduire automatiquement chaque interaction de bureau sur téléphone.</td></tr></tbody></table><p>Les lots sont découpables. L1a ne doit pas bloquer un premier Steps ou une amélioration ciblée de BottomSheet ; les dépendances réelles déterminent le détail des incréments. L5 constitue une réserve de besoins à arbitrer, pas un engagement de porter l’intégralité du catalogue web à l’identique.</p><h2 id="criteres-communs-a-chaque-composant-porte" tabindex="-1">Critères communs à chaque composant porté <a class="header-anchor" href="#criteres-communs-a-chaque-composant-porte" aria-label="Permalink to &quot;Critères communs à chaque composant porté&quot;">​</a></h2><ul><li>Conserver l’identité SIA : tokens, clair/sombre, couleurs personnalisées, messages d’erreur rouges et mêmes états sémantiques utiles.</li><li>Garder une API contrôlée cohérente avec le headless ; documenter les différences d’événements, refs et interactions propres à React Native.</li><li>Vérifier cibles tactiles, noms et valeurs accessibles, focus, grands textes, lecteur d’écran et navigation avec clavier externe lorsque pertinente.</li><li>Préserver la saisie et le défilement ; vérifier clavier logiciel, Retour Android, liens directs et cycle de vie de l’app lorsque le composant les utilise.</li><li>Respecter la réduction des animations, interrompre proprement les transitions et exposer les réglages utiles sans imposer des animations à l’application.</li><li>Ajouter des tests de comportement utiles, une démonstration et la documentation du même changement. Consigner séparément compilation et validation sur appareil.</li></ul><h2 id="maintenance-de-la-matrice" tabindex="-1">Maintenance de la matrice <a class="header-anchor" href="#maintenance-de-la-matrice" aria-label="Permalink to &quot;Maintenance de la matrice&quot;">​</a></h2><p>À chaque ajout ou changement de responsabilité publique : mettre à jour la ligne, son statut, les écarts encore présents et les preuves de validation. Ajouter une ligne lorsqu’un module web public apparaît ; mettre les API uniquement natives dans leur section dédiée. Le backlog indique précisément ce qui est effectivement livré ; cette matrice conserve aussi les besoins <strong>prévus</strong>.</p><p>Ne pas marquer un composant Disponible uniquement parce qu’il utilise le même nom, qu’une démo ressemble au web ou qu’un hook existe dans headless. En cas de nouveau sous-composant ou d’option majeure, reprendre l’examen du contrat avant de modifier son statut.</p><p>Le <a href="./../guides/composants-mobiles.html">guide du lot présentation et organisation</a> décrit les APIs livrées, les menus de la démo et les limites de gestes restantes.</p><p>Le <a href="./../guides/listes-parcours-mobiles.html">guide listes et parcours métier</a> décrit les APIs et les limites du socle L3 livré.</p><p>Le <a href="./../guides/affichage-metier-mobile.html">guide affichage métier mobile</a> précise les variantes et les limites du tableau de bord et de l’historique.</p><p>Le <a href="./../guides/actions-selection-mobile.html">guide actions et sélection mobiles</a> décrit les menus, arbres et actions groupées, avec leurs limites.</p>',15))])}const S=i(p,[["render",m]]);export{x as __pageData,S as default};
